package com.tsghub;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Skill;
import net.runelite.client.util.Text;

final class ActivityDetector
{
	static final long RECENT_MILLIS = 90_000;
	static final long SLAYER_MILLIS = 300_000;
	private static final Set<Skill> COMBAT = EnumSet.of(Skill.ATTACK, Skill.STRENGTH, Skill.DEFENCE, Skill.RANGED, Skill.HITPOINTS);
	private static final Map<String, String> BOSSES = loadBosses();

	private final Map<Skill, Integer> xp = new EnumMap<>(Skill.class);
	private Skill lastSkill;
	private long lastSkillAt;
	private long lastCombatAt;
	private long lastSlayerAt;
	private long slayerTarget;
	private int slayerRemaining;
	private String slayerTask;
	private String lastBoss;
	private long lastBossAt;

	static String bossFor(String npcName)
	{
		return npcName == null ? null : BOSSES.get(Text.removeTags(npcName).trim().toLowerCase(Locale.ROOT));
	}

	void onXp(Skill skill, int value, long now)
	{
		Integer previous = xp.put(skill, value);
		if (previous == null || value <= previous) return;
		if (skill == Skill.HITPOINTS) lastCombatAt = now;
		else if (skill != Skill.SLAYER && !COMBAT.contains(skill))
		{
			lastSkill = skill;
			lastSkillAt = now;
		}
	}

	void onOpponent(String npcName, long now)
	{
		String boss = bossFor(npcName);
		if (boss == null) return;
		lastBoss = boss;
		lastBossAt = now;
	}

	void onSlayerTask(long target, int remaining, String task, long now)
	{
		if (remaining <= 0)
		{
			clearSlayer();
			return;
		}
		if (target == slayerTarget && remaining < slayerRemaining) lastSlayerAt = now;
		slayerTarget = target;
		slayerRemaining = remaining;
		slayerTask = task;
	}

	boolean needsSlayerTaskName()
	{
		return slayerRemaining > 0 && slayerTask == null;
	}

	private void clearSlayer()
	{
		lastSlayerAt = 0;
		slayerTarget = 0;
		slayerRemaining = 0;
		slayerTask = null;
	}

	void reset()
	{
		xp.clear();
		lastSkill = null;
		lastSkillAt = 0;
		lastCombatAt = 0;
		clearSlayer();
		lastBoss = null;
		lastBossAt = 0;
	}

	String activity(AreaNames.Area area, long now)
	{
		if (lastBoss != null && now - lastBossAt < RECENT_MILLIS) return "Bossing - " + lastBoss;
		if (area != null)
		{
			if (area.type == AreaNames.Type.BOSSES) return "Bossing - " + area.name;
			if (area.type == AreaNames.Type.RAIDS) return "Raiding - " + area.name;
			if (area.type == AreaNames.Type.MINIGAMES) return "Minigame - " + area.name;
		}
		boolean fighting = lastCombatAt > 0 && now - lastCombatAt < RECENT_MILLIS;
		boolean slaying = lastSlayerAt > 0 && now - lastSlayerAt < (fighting ? SLAYER_MILLIS : RECENT_MILLIS);
		if (slaying) return slayerTask == null ? "Slayer" : "Slayer - " + slayerTask;
		if (fighting) return "Combat";
		if (lastSkill != null && now - lastSkillAt < RECENT_MILLIS) return "Skilling - " + lastSkill.getName();
		return "Idle";
	}

	private static Map<String, String> loadBosses()
	{
		Map<String, String> bosses = new HashMap<>();
		InputStream in = ActivityDetector.class.getResourceAsStream("bosses.tsv");
		if (in == null) return bosses;
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#")) continue;
				String[] parts = line.split("\t");
				if (parts.length < 2) continue;
				for (String npc : parts[1].split(",")) bosses.put(npc.trim().toLowerCase(Locale.ROOT), parts[0]);
			}
		}
		catch (IOException ignored) { }
		return bosses;
	}
}

package com.tsghub;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.coords.WorldPoint;

final class AreaNames
{
	enum Type { BOSSES, RAIDS, MINIGAMES, DUNGEONS, CITIES, REGIONS }

	static final class Area
	{
		final String name;
		final Type type;

		Area(String name, Type type)
		{
			this.name = name;
			this.type = type;
		}
	}

	private static final Map<Integer, Area> BY_REGION = load();

	private AreaNames() {}

	static Area forRegion(int region)
	{
		return BY_REGION.get(region);
	}

	static Area at(WorldPoint point)
	{
		Area named = forRegion(point.getRegionID());
		if (named != null && (named.type == Type.BOSSES || named.type == Type.RAIDS)) return named;
		int level = wildernessLevel(point);
		return level > 0 ? new Area("Wilderness lvl " + level, Type.REGIONS) : named;
	}

	static int wildernessLevel(WorldPoint point)
	{
		int x = point.getX();
		int y = point.getY();
		if (x < 2944 || x > 3391) return 0;
		if (y >= 3520 && y <= 3967) return (y - 3520) / 8 + 1;
		if (y >= 9920 && y <= 10367) return (y - 9920) / 8 + 1;
		return 0;
	}

	private static Map<Integer, Area> load()
	{
		Map<Integer, Area> areas = new HashMap<>();
		InputStream in = AreaNames.class.getResourceAsStream("areas.tsv");
		if (in == null) return areas;
		try (BufferedReader reader = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
		{
			String line;
			while ((line = reader.readLine()) != null)
			{
				if (line.isEmpty() || line.startsWith("#")) continue;
				String[] parts = line.split("\t");
				if (parts.length < 3) continue;
				Area area = new Area(parts[1], Type.valueOf(parts[0]));
				for (String id : parts[2].split(",")) areas.putIfAbsent(Integer.parseInt(id.trim()), area);
			}
		}
		catch (IOException | IllegalArgumentException ignored) { }
		return areas;
	}
}

package com.tsghub;

import java.util.Locale;

public final class PlayerNames
{
	private PlayerNames()
	{
	}

	public static String normalize(String name)
	{
		return name == null ? "" : name.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]", "");
	}
}

package com.tsghub;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParseException;
import com.google.gson.JsonParser;
import java.util.concurrent.TimeUnit;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;
import okhttp3.ResponseBody;

final class TsgHubApi
{
	static final class HttpError extends IllegalStateException
	{
		final int status;

		HttpError(int status, String message)
		{
			super(message);
			this.status = status;
		}
	}

	private static final MediaType JSON = MediaType.parse("application/json; charset=utf-8");
	private final String baseUrl;
	private final OkHttpClient http;

	TsgHubApi(OkHttpClient http, String baseUrl)
	{
		this.baseUrl = baseUrl.replaceAll("/+$", "");
		this.http = http.newBuilder()
			.connectTimeout(5, TimeUnit.SECONDS)
			.readTimeout(8, TimeUnit.SECONDS)
			.build();
	}

	JsonObject request(String method, String path, String token, JsonObject payload) throws Exception
	{
		Request.Builder builder = new Request.Builder()
			.url(baseUrl + path)
			.header("Accept", "application/json")
			.header(TsgHubVersion.HEADER, TsgHubVersion.VERSION);
		if (token != null && !token.isEmpty()) builder.header("Authorization", "Bearer " + token);
		RequestBody body = payload == null ? null : RequestBody.create(JSON, payload.toString());
		// OkHttp requires a body for POST/PATCH/PUT.
		if (body == null && !"GET".equals(method) && !"DELETE".equals(method)) body = RequestBody.create(JSON, "{}");
		builder.method(method, body);

		try (Response response = http.newCall(builder.build()).execute())
		{
			ResponseBody responseBody = response.body();
			String text = responseBody == null ? "" : responseBody.string();
			JsonObject json = parseObject(text);
			if (!response.isSuccessful())
			{
				String message = json != null && json.has("error") && json.get("error").isJsonPrimitive()
					? json.get("error").getAsString()
					: "Service returned HTTP " + response.code();
				throw new HttpError(response.code(), message);
			}
			if (json == null) throw new IllegalStateException("Service returned an unexpected response");
			return json;
		}
	}

	private static JsonObject parseObject(String text)
	{
		if (text.isEmpty()) return new JsonObject();
		try
		{
			JsonElement element = new JsonParser().parse(text);
			return element.isJsonObject() ? element.getAsJsonObject() : null;
		}
		catch (JsonParseException e) { return null; }
	}
}

package com.tsghub;

import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.DefaultListModel;
import javax.swing.JLabel;
import javax.swing.JList;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;
import javax.swing.ListSelectionModel;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import net.runelite.client.hiscore.HiscoreSkill;
import net.runelite.client.hiscore.HiscoreSkillType;

final class TsgHubBossPicker extends JPanel
{
	static final List<String> BOSSES = bossNames();

	private final JTextField field = new JTextField();
	private final DefaultListModel<String> results = new DefaultListModel<>();
	private final JList<String> resultList = new JList<>(results);
	private final JScrollPane resultScroll = new JScrollPane(resultList);
	private final JLabel hint = TsgHubUi.caption("");
	private final Runnable onChosen;

	TsgHubBossPicker(String caption, Runnable onChosen)
	{
		this.onChosen = onChosen;
		setLayout(new javax.swing.BoxLayout(this, javax.swing.BoxLayout.Y_AXIS));
		setOpaque(false);
		setAlignmentX(LEFT_ALIGNMENT);
		JLabel label = TsgHubUi.caption(caption);
		add(label);
		add(Box.createVerticalStrut(3));

		field.putClientProperty("JTextField.placeholderText", "e.g. Vorkath");
		field.setAlignmentX(LEFT_ALIGNMENT);
		field.getDocument().addDocumentListener(new DocumentListener()
		{
			@Override public void insertUpdate(DocumentEvent e) { filter(); }
			@Override public void removeUpdate(DocumentEvent e) { filter(); }
			@Override public void changedUpdate(DocumentEvent e) { filter(); }
		});
		field.addActionListener(e -> {
			if (resultScroll.isVisible() && !results.isEmpty()) choose(results.get(Math.max(0, resultList.getSelectedIndex())));
		});
		field.addKeyListener(new KeyAdapter()
		{
			@Override public void keyPressed(KeyEvent e)
			{
				if (!resultScroll.isVisible() || results.isEmpty()) return;
				int index = resultList.getSelectedIndex();
				if (e.getKeyCode() == KeyEvent.VK_DOWN) index = Math.min(results.size() - 1, index + 1);
				else if (e.getKeyCode() == KeyEvent.VK_UP) index = Math.max(0, index - 1);
				else if (e.getKeyCode() == KeyEvent.VK_ESCAPE) { hideResults(); return; }
				else return;
				resultList.setSelectedIndex(index);
				resultList.ensureIndexIsVisible(index);
				e.consume();
			}
		});
		add(TsgHubUi.fitHeight(field));

		resultList.setSelectionMode(ListSelectionModel.SINGLE_SELECTION);
		resultList.setVisibleRowCount(6);
		resultList.setBackground(TsgHubUi.CARD);
		resultList.setCellRenderer((list, value, index, selected, focus) -> {
			JLabel row = new JLabel(value);
			row.setOpaque(true);
			row.setBorder(BorderFactory.createEmptyBorder(3, 6, 3, 6));
			row.setBackground(selected ? TsgHubUi.CARD_HOVER : TsgHubUi.CARD);
			row.setForeground(TsgHubUi.TEXT);
			return row;
		});
		resultList.addMouseListener(new MouseAdapter()
		{
			@Override public void mouseClicked(MouseEvent e)
			{
				int index = resultList.locationToIndex(e.getPoint());
				if (index >= 0 && resultList.getCellBounds(index, index).contains(e.getPoint())) choose(results.get(index));
			}
		});
		resultScroll.setBorder(BorderFactory.createLineBorder(TsgHubUi.BORDER));
		resultScroll.setAlignmentX(LEFT_ALIGNMENT);
		resultScroll.setVisible(false);
		add(resultScroll);
		hint.setText(defaultHint());
		add(hint);
		setBorder(BorderFactory.createEmptyBorder(0, 0, 10, 0));
	}

	String getText()
	{
		return field.getText().trim();
	}

	void setText(String name)
	{
		field.setText(name == null ? "" : name);
		hideResults();
	}

	JTextField field()
	{
		return field;
	}

	private void filter()
	{
		String query = field.getText().trim().toLowerCase(Locale.ROOT);
		results.clear();
		if (query.isEmpty() || BOSSES.stream().anyMatch(b -> b.equalsIgnoreCase(query)))
		{
			hideResults();
			if (!query.isEmpty()) hint.setText("Counts \"" + field.getText().trim() + "\" kill count messages.");
			return;
		}
		List<String> prefix = new ArrayList<>();
		List<String> contains = new ArrayList<>();
		for (String boss : BOSSES)
		{
			String lower = boss.toLowerCase(Locale.ROOT);
			if (lower.startsWith(query) || lower.contains(" " + query)) prefix.add(boss);
			else if (lower.contains(query)) contains.add(boss);
		}
		prefix.addAll(contains);
		for (String boss : prefix) results.addElement(boss);
		resultList.setVisibleRowCount(Math.max(1, Math.min(6, results.size())));
		resultScroll.setVisible(!results.isEmpty());
		if (!results.isEmpty()) resultList.setSelectedIndex(0);
		hint.setText(results.isEmpty()
			? "Not in RuneLite's boss list. It will still count if this name appears in the kill count message."
			: "Click a boss (or press Enter) to pick it.");
		revalidate();
		repaint();
	}

	private void choose(String boss)
	{
		field.setText(boss);
		hideResults();
		hint.setText("Counts \"" + boss + "\" kill count messages.");
		if (onChosen != null) onChosen.run();
	}

	private void hideResults()
	{
		resultScroll.setVisible(false);
		hint.setText(defaultHint());
		revalidate();
	}

	private static String defaultHint()
	{
		return "Type to search bosses, or enter any name shown in its kill count message.";
	}

	private static List<String> bossNames()
	{
		List<String> names = new ArrayList<>();
		for (HiscoreSkill skill : HiscoreSkill.values())
		{
			if (skill.getType() != HiscoreSkillType.BOSS) continue;
			String name = skill.getName();
			if (name.startsWith("Chambers of Xeric") || name.startsWith("Theatre of Blood") || name.startsWith("Tombs of Amascut")) continue;
			names.add(name);
		}
		names.sort(String.CASE_INSENSITIVE_ORDER);
		return names;
	}
}

package com.tsghub;

import com.google.gson.JsonArray;
import com.google.gson.JsonObject;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Deque;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentLinkedDeque;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.callback.ClientThread;

final class TsgHubCompetitionTracker
{
	static final Pattern KILL_COUNT = Pattern.compile("(?:kill count|kill-count)[^0-9]*([0-9][0-9,]*)");
	private static final long XP_FLUSH_SECONDS = 10;
	private static final long SCHEDULE_CHECK_SECONDS = 60;
	private static final int REWARD_TICKS = 2;
	static final Set<Integer> REWARD_INTERFACES = Set.of(
		InterfaceID.QUESTSCROLL,
		InterfaceID.XPREWARD,
		InterfaceID.PEST_REWARDSHOP,
		InterfaceID.BARBASSAULT_REWARD_SHOP,
		InterfaceID.SOUL_WARS_REWARDS,
		InterfaceID.AGILITYARENA_REWARDS,
		InterfaceID.TREK_REWARDS);

	private final Supplier<TsgHubApi> api;
	private final ScheduledExecutorService executor;
	private final Client client;
	private final ClientThread clientThread;
	private volatile List<JsonObject> tracked = Collections.emptyList();
	private volatile List<JsonObject> joined = Collections.emptyList();
	// Flushed on a delay so each XP drop doesn't send a request.
	private final Map<String, PendingXp> pendingXp = new ConcurrentHashMap<>();
	private final Map<Skill, Integer> lastXp = new ConcurrentHashMap<>();
	private final Deque<XpGain> recentGains = new ConcurrentLinkedDeque<>();
	private final Set<Integer> openRewards = ConcurrentHashMap.newKeySet();
	private volatile int rewardTick = Integer.MIN_VALUE;

	TsgHubCompetitionTracker(Supplier<TsgHubApi> api, ScheduledExecutorService executor, Client client, ClientThread clientThread)
	{
		this.api = api;
		this.executor = executor;
		this.client = client;
		this.clientThread = clientThread;
		executor.scheduleAtFixedRate(this::checkSchedule, SCHEDULE_CHECK_SECONDS, SCHEDULE_CHECK_SECONDS, TimeUnit.SECONDS);
	}

	void setEvents(JsonArray events)
	{
		List<JsonObject> found = new ArrayList<>();
		for (int i = 0; i < events.size(); i++)
		{
			JsonObject event = events.get(i).getAsJsonObject();
			String type = TsgHubUi.str(event, "type");
			if (!("skill".equals(type) || "boss".equals(type)) || "ended".equals(TsgHubUi.str(event, "status"))) continue;
			if (token(event).isEmpty()) continue;
			found.add(event);
		}
		tracked = found;
		joined = running(found);
		reportAllSkills();
	}

	void clear()
	{
		tracked = Collections.emptyList();
		joined = Collections.emptyList();
		pendingXp.clear();
		lastXp.clear();
		recentGains.clear();
		openRewards.clear();
		rewardTick = Integer.MIN_VALUE;
	}

	private void checkSchedule()
	{
		List<JsonObject> running = running(tracked);
		if (ids(running).equals(ids(joined))) return;
		joined = running;
		reportAllSkills();
	}

	private static List<JsonObject> running(List<JsonObject> events)
	{
		List<JsonObject> running = new ArrayList<>();
		Instant now = Instant.now();
		for (JsonObject event : events)
			if (TsgHubUi.running(event, now)) running.add(event);
		return running;
	}

	private static List<String> ids(List<JsonObject> events)
	{
		List<String> ids = new ArrayList<>();
		for (JsonObject event : events) ids.add(TsgHubUi.str(event, "id"));
		return ids;
	}

	void reportAllSkills()
	{
		List<JsonObject> events = joined;
		if (events.stream().noneMatch(e -> "skill".equals(TsgHubUi.str(e, "type")))) return;
		clientThread.invokeLater(() -> {
			if (client.getLocalPlayer() == null) return;
			for (JsonObject event : events)
			{
				if (!"skill".equals(TsgHubUi.str(event, "type"))) continue;
				Skill skill = skill(event);
				if (skill != null) queueXp(event, client.getSkillExperience(skill), 0);
			}
		});
	}

	void onXp(Skill skill, int xp)
	{
		Integer previous = lastXp.put(skill, xp);
		int tick = client.getTickCount();
		if (previous != null && xp > previous)
		{
			if (rewardActive(tick)) excludeXp(skill, xp - previous);
			else recentGains.addLast(new XpGain(tick, skill, xp - previous));
		}
		while (!recentGains.isEmpty() && tick - recentGains.peekFirst().tick > REWARD_TICKS) recentGains.pollFirst();
		for (JsonObject event : joined)
			if ("skill".equals(TsgHubUi.str(event, "type")) && skill == skill(event)) queueXp(event, xp, 0);
	}

	void onInterfaceOpened(int groupId)
	{
		if (!REWARD_INTERFACES.contains(groupId)) return;
		openRewards.add(groupId);
		int tick = client.getTickCount();
		rewardTick = tick;
		for (XpGain gain; (gain = recentGains.pollFirst()) != null; )
			if (tick - gain.tick <= REWARD_TICKS) excludeXp(gain.skill, gain.xp);
	}

	void onInterfaceClosed(int groupId)
	{
		if (openRewards.remove(groupId)) rewardTick = client.getTickCount();
	}

	private boolean rewardActive(int tick)
	{
		return !openRewards.isEmpty() || tick - rewardTick <= REWARD_TICKS;
	}

	private void excludeXp(Skill skill, int xp)
	{
		Integer total = lastXp.get(skill);
		if (total == null) return;
		for (JsonObject event : joined)
			if ("skill".equals(TsgHubUi.str(event, "type")) && skill == skill(event)) queueXp(event, total, xp);
	}

	void onChat(String message)
	{
		if (!message.contains("kill count") && !message.contains("kill-count")) return;
		Matcher count = KILL_COUNT.matcher(message);
		if (!count.find()) return;
		int kills;
		try { kills = Integer.parseInt(count.group(1).replace(",", "")); }
		catch (NumberFormatException e) { return; }
		for (JsonObject event : joined)
		{
			JsonObject config = config(event);
			if (!"boss".equals(TsgHubUi.str(event, "type")) || "loot".equals(TsgHubUi.str(config, "signal"))) continue;
			if (!message.contains(TsgHubUi.str(config, "npcName").toLowerCase(Locale.ROOT))) continue;
			JsonObject body = new JsonObject();
			body.addProperty("value", kills);
			submit(event, body);
		}
	}

	void onNpcLoot(String npcName, int tick)
	{
		if (npcName == null) return;
		for (JsonObject event : joined)
		{
			JsonObject config = config(event);
			if (!"boss".equals(TsgHubUi.str(event, "type")) || !"loot".equals(TsgHubUi.str(config, "signal"))) continue;
			if (!npcName.equalsIgnoreCase(TsgHubUi.str(config, "npcName"))) continue;
			JsonObject body = new JsonObject();
			body.addProperty("quantity", 1);
			body.addProperty("evidenceId", "loot-" + npcName.toLowerCase(Locale.ROOT) + "-" + tick);
			submit(event, body);
		}
	}

	private void queueXp(JsonObject event, int xp, int excluded)
	{
		String id = TsgHubUi.str(event, "id");
		String token = token(event);
		if (token.isEmpty() || executor.isShutdown()) return;
		boolean[] schedule = {false};
		pendingXp.compute(id, (key, previous) -> {
			schedule[0] = previous == null;
			return new PendingXp(Math.max(xp, previous == null ? 0 : previous.xp), token, excluded + (previous == null ? 0 : previous.excluded));
		});
		if (!schedule[0]) return;
		executor.schedule(() -> {
			PendingXp latest = pendingXp.remove(id);
			if (latest == null) return;
			JsonObject body = new JsonObject();
			body.addProperty("value", latest.xp);
			if (latest.excluded > 0)
			{
				body.addProperty("excluded", latest.excluded);
				body.addProperty("evidenceId", "reward-" + UUID.randomUUID());
			}
			send(event, latest.token, body);
		}, XP_FLUSH_SECONDS, TimeUnit.SECONDS);
	}

	private void submit(JsonObject event, JsonObject body)
	{
		String token = token(event);
		if (!token.isEmpty() && !executor.isShutdown()) executor.submit(() -> send(event, token, body));
	}

	private void send(JsonObject event, String token, JsonObject body)
	{
		try { api.get().request("POST", "/v1/events/" + TsgHubUi.str(event, "id") + "/progress", token, body); }
		catch (Exception ignored) { /* The next XP change or kill reports the latest total again. */ }
	}

	private static String token(JsonObject event)
	{
		return TsgHubSession.get("memberToken:" + TsgHubUi.str(event, "id"));
	}

	private static JsonObject config(JsonObject event)
	{
		return event.has("config") && event.get("config").isJsonObject() ? event.getAsJsonObject("config") : new JsonObject();
	}

	private static Skill skill(JsonObject event)
	{
		try { return Skill.valueOf(TsgHubUi.str(config(event), "skill")); }
		catch (IllegalArgumentException e) { return null; }
	}

	private static final class PendingXp
	{
		private final int xp;
		private final String token;
		private final int excluded;
		private PendingXp(int xp, String token, int excluded) { this.xp = xp; this.token = token; this.excluded = excluded; }
	}

	private static final class XpGain
	{
		private final int tick;
		private final Skill skill;
		private final int xp;
		private XpGain(int tick, Skill skill, int xp) { this.tick = tick; this.skill = skill; this.xp = xp; }
	}
}

