import net.runelite.api.gameval.SpriteID;
import net.runelite.client.game.SpriteManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.util.ImageUtil;
import com.tsghub.group.ImgUtil;

import javax.swing.JLabel;
import javax.swing.JPanel;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.image.BufferedImage;

public class TotalPanelSlot extends JPanel
{
	private static final int SLOT_HEIGHT = 22;
	private static final int SLOT_WIDTH = PlayerSkillsPanel.PANEL_SIZE.width + 7;
	private static final int _1_5TH_SLOT_WIDTH = SLOT_WIDTH / 5;

	private final JLabel levelLabel = new JLabel();
	private BufferedImage background;
	private BufferedImage backgroundLeft;
	private BufferedImage backgroundRight;
	private BufferedImage backgroundCenter;

	@Override
	protected void paintComponent(Graphics g)
	{
		super.paintComponent(g);
		if (background == null)
		{
			return;
		}

		g.drawImage(background, 0, 0, null);
	}

	private void updateBackgroundImage()
	{
		if (backgroundLeft != null && backgroundRight != null && backgroundCenter != null)
		{
			final BufferedImage temp = ImgUtil.combineImages(backgroundLeft, backgroundCenter);
			background = ImgUtil.combineImages(temp, backgroundRight);
			this.repaint();
		}
	}

	TotalPanelSlot(final int totalLevel, final SpriteManager spriteManager)
	{
		super();
		setOpaque(false);

		spriteManager.getSpriteAsync(SpriteID.Miscgraphics2._4, 0, img ->
		{
			backgroundLeft = resize_edge(img);
			updateBackgroundImage();
		});
		spriteManager.getSpriteAsync(SpriteID.Miscgraphics2._5, 0, img ->
		{
			backgroundRight = resize_edge(img);
			updateBackgroundImage();
		});
		spriteManager.getSpriteAsync(SpriteID.Miscgraphics2._6, 0, img ->
		{
			backgroundCenter = resize_middle(img);
			updateBackgroundImage();
		});

		setPreferredSize(new Dimension(PlayerSkillsPanel.PANEL_SIZE.width, SLOT_HEIGHT));
		setLayout(new GridBagLayout());
		final GridBagConstraints c = new GridBagConstraints();
		c.gridx = 0;
		c.gridy = 0;
		c.insets = new Insets(3, 0, 0, 0);

		final JLabel textLabel = new JLabel("Total level:");
		textLabel.setFont(FontManager.getRunescapeSmallFont());
		textLabel.setForeground(Color.YELLOW);
		textLabel.setAlignmentY(BOTTOM_ALIGNMENT);
		add(textLabel, c);

		if (totalLevel > 0)
		{
			levelLabel.setText(String.valueOf(totalLevel));
		}
		levelLabel.setFont(FontManager.getRunescapeSmallFont());
		levelLabel.setForeground(Color.YELLOW);
		levelLabel.setAlignmentY(BOTTOM_ALIGNMENT);
		c.gridx++;
		add(levelLabel, c);
	}

	private BufferedImage resize_edge(final BufferedImage img)
	{
		return ImageUtil.resizeImage(img, _1_5TH_SLOT_WIDTH, SLOT_HEIGHT);
	}

	private BufferedImage resize_middle(final BufferedImage img)
	{
		return ImageUtil.resizeImage(img, _1_5TH_SLOT_WIDTH * 3, SLOT_HEIGHT);
	}

	public void updateTotalLevel(final int level)
	{
		levelLabel.setText(String.valueOf(level));
		levelLabel.repaint();
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

import com.google.gson.JsonObject;
import java.awt.Color;
import java.time.Instant;
import java.time.ZoneId;
import java.util.Arrays;
import java.util.Collections;
import org.junit.Test;

public class DropsPanelTest
{
	@Test
	public void formatGp()
	{
		assertEquals("", TsgHubUi.formatGp(0));
		assertEquals("950 gp", TsgHubUi.formatGp(950));
		assertEquals("7.2K", TsgHubUi.formatGp(7_250));
		assertEquals("1.5M", TsgHubUi.formatGp(1_512_345));
		assertEquals("12M", TsgHubUi.formatGp(12_000_000));
		assertEquals("1.2B", TsgHubUi.formatGp(1_234_567_890L));
	}

	@Test
	public void dropItem()
	{
		assertEquals("Abyssal whip", TsgHubSidebarPanel.dropItem(drop("Abyssal whip", 1)));
		assertEquals("3 x Dragon bones", TsgHubSidebarPanel.dropItem(drop("Dragon bones", 3)));
		assertEquals("Tumeken's shadow", TsgHubSidebarPanel.dropItem(drop("Tumeken's shadow (uncharged)", 1)));
		assertEquals("3 x Onyx bolts", TsgHubSidebarPanel.dropItem(drop("Onyx bolts (e)", 3)));
	}

	@Test
	public void dropTags()
	{
		JsonObject raid = drop("Twisted bow", 1);
		raid.addProperty("kind", "raid");
		assertEquals(Arrays.asList("CoX"), TsgHubSidebarPanel.dropTags(raid));
		raid.addProperty("newLog", true);
		assertEquals(Arrays.asList("CoX", "Log"), TsgHubSidebarPanel.dropTags(raid));
		JsonObject clog = drop("Dragon warhammer", 1);
		clog.addProperty("kind", "clog");
		assertEquals(Arrays.asList("Log"), TsgHubSidebarPanel.dropTags(clog));
		JsonObject dupe = drop("Vorki", 1);
		dupe.addProperty("kind", "dupe");
		assertEquals(Arrays.asList("Dupe pet"), TsgHubSidebarPanel.dropTags(dupe));
		JsonObject plain = drop("Abyssal whip", 1);
		plain.addProperty("kind", "drop");
		assertEquals(Collections.emptyList(), TsgHubSidebarPanel.dropTags(plain));
	}

	@Test
	public void raidName()
	{
		assertEquals("ToB", TsgHubSidebarPanel.raidName("Scythe of vitur (uncharged)"));
		assertEquals("ToA", TsgHubSidebarPanel.raidName("Elidinis' ward"));
		assertEquals("CoX", TsgHubSidebarPanel.raidName("Dexterous prayer scroll"));
		assertEquals("Raid", TsgHubSidebarPanel.raidName("Mystery box"));
	}

	@Test
	public void dropDay()
	{
		ZoneId zone = ZoneId.of("America/New_York");
		Instant now = Instant.parse("2026-09-28T16:00:00Z");
		assertEquals("Today", TsgHubSidebarPanel.dropDay("2026-09-28T05:00:00Z", now, zone));
		assertEquals("Yesterday", TsgHubSidebarPanel.dropDay("2026-09-28T03:00:00Z", now, zone));
		assertEquals("26 Sep 2026", TsgHubSidebarPanel.dropDay("2026-09-26T12:00:00Z", now, zone));
		assertEquals("Earlier", TsgHubSidebarPanel.dropDay("", now, zone));
	}

	@Test
	public void dropWhen()
	{
		ZoneId zone = ZoneId.of("America/New_York");
		Instant now = Instant.parse("2026-09-28T16:00:00Z");
		assertEquals("11h", TsgHubSidebarPanel.dropWhen("2026-09-28T05:00:00Z", now, zone));
		assertEquals("23:00", TsgHubSidebarPanel.dropWhen("2026-09-28T03:00:00Z", now, zone));
		assertEquals("", TsgHubSidebarPanel.dropWhen("", now, zone));
	}

	@Test
	public void coinColor()
	{
		assertEquals(new Color(255, 255, 0), TsgHubUi.coinColor(99_999));
		assertEquals(Color.WHITE, TsgHubUi.coinColor(803_300));
		assertEquals(new Color(0, 255, 128), TsgHubUi.coinColor(10_000_000));
	}

	@Test
	public void broadcastFilter()
	{
		assertEquals("Iron Alice received a drop: Abyssal whip (1,512,345 coins).",
			TsgHubDrops.broadcast("<img=3>Iron Alice received a drop: <col=ef1020>Abyssal whip</col> (1,512,345 coins)."));
		assertEquals("Bob received special loot from a raid: Twisted bow.", TsgHubDrops.broadcast("Bob received special loot from a raid: Twisted bow."));
		assertEquals("itsHammerKR has a funny feeling like he would have been followed: Vorki at 912 killcount from Vorkath.",
			TsgHubDrops.broadcast("itsHammerKR has a funny feeling like he would have been followed: Vorki at 912 killcount from Vorkath."));
		assertNull(TsgHubDrops.broadcast("Bob has reached combat level 100."));
		assertNull(TsgHubDrops.broadcast(null));
	}

	private static JsonObject drop(String item, int quantity)
	{
		JsonObject drop = new JsonObject();
		drop.addProperty("item", item);
		drop.addProperty("quantity", quantity);
		return drop;
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import com.google.gson.JsonObject;
import java.time.Duration;
import java.time.Instant;
import java.time.ZoneId;
import org.junit.Test;

public class EventTimesTest
{
	private static final ZoneId PERTH = ZoneId.of("Australia/Perth");
	private static final ZoneId ADELAIDE = ZoneId.of("Australia/Adelaide");
	private static final ZoneId BRISBANE = ZoneId.of("Australia/Brisbane");
	private static final ZoneId SYDNEY = ZoneId.of("Australia/Sydney");
	private static final Instant NOW = Instant.parse("2026-10-04T02:00:00Z");

	@Test
	public void sameInstantInEachZone()
	{
		Instant start = Instant.parse("2026-10-05T08:00:00Z");
		Instant end = Instant.parse("2026-10-05T10:30:00Z");
		assertEquals("Mon 5 Oct, 4-6:30pm AWST", TsgHubUi.timeRange(start, end, PERTH, NOW));
		assertEquals("Mon 5 Oct, 6:30-9pm ACDT", TsgHubUi.timeRange(start, end, ADELAIDE, NOW));
		assertEquals("Mon 5 Oct, 6-8:30pm AEST", TsgHubUi.timeRange(start, end, BRISBANE, NOW));
		assertEquals("Mon 5 Oct, 7-9:30pm AEDT", TsgHubUi.timeRange(start, end, SYDNEY, NOW));
	}

	@Test
	public void rangeAcrossDaylightSavingShowsBothZones()
	{
		Instant start = Instant.parse("2026-09-20T09:00:00Z");
		Instant end = Instant.parse("2026-10-11T08:00:00Z");
		assertEquals("Sun 20 Sep, 7pm AEST to Sun 11 Oct, 7pm AEDT", TsgHubUi.timeRange(start, end, SYDNEY, NOW));
		assertEquals("Sun 20 Sep, 7pm to Sun 11 Oct, 6pm AEST", TsgHubUi.timeRange(start, end, BRISBANE, NOW));
	}

	@Test
	public void openEndedAndOtherYears()
	{
		Instant start = Instant.parse("2027-01-02T09:00:00Z");
		assertEquals("Sat 2 Jan 2027, 8pm AEDT", TsgHubUi.timeRange(start, null, SYDNEY, NOW));
		assertEquals("Time TBD", TsgHubUi.timeRange(null, null, SYDNEY, NOW));
		assertEquals("Mon 5 Oct, 11:30am-1pm AEDT", TsgHubUi.timeRange(Instant.parse("2026-10-05T00:30:00Z"), Instant.parse("2026-10-05T02:00:00Z"), SYDNEY, NOW));
	}

	@Test
	public void relativeHints()
	{
		Instant start = NOW.plus(Duration.ofHours(3));
		Instant end = start.plus(Duration.ofDays(2)).plus(Duration.ofHours(4));
		assertEquals("starts in 3h", TsgHubUi.relativeTime(start, end, NOW));
		assertEquals("starts in 2h 30m", TsgHubUi.relativeTime(NOW.plus(Duration.ofMinutes(150)), end, NOW));
		assertEquals("starts in 1m", TsgHubUi.relativeTime(NOW.plusSeconds(10), end, NOW));
		assertEquals("ends in 2d 4h", TsgHubUi.relativeTime(start, end, start));
		assertEquals("ends in 3d", TsgHubUi.relativeTime(start, start.plus(Duration.ofDays(3)), start));
		assertEquals("ended", TsgHubUi.relativeTime(start, end, end));
		assertEquals("happening now", TsgHubUi.relativeTime(start, null, start));
	}

	@Test
	public void zoneLabel()
	{
		assertEquals("AEDT (Australia/Sydney)", TsgHubUi.zoneLabel(SYDNEY, NOW));
		assertEquals("AWST (Australia/Perth)", TsgHubUi.zoneLabel(PERTH, NOW));
		assertEquals("UTC", TsgHubUi.zoneLabel(ZoneId.of("UTC"), NOW));
	}

	@Test
	public void eventInstants()
	{
		JsonObject event = new JsonObject();
		event.addProperty("type", "bingo");
		event.addProperty("startsAt", "2026-10-05T08:00:00Z");
		event.addProperty("endsAt", "2026-10-12T08:00:00Z");
		event.addProperty("startDate", "2000-01-01");
		assertEquals(Instant.parse("2026-10-05T08:00:00Z"), TsgHubUi.eventStart(event));
		assertEquals(Instant.parse("2026-10-12T08:00:00Z"), TsgHubUi.eventEnd(event));
		assertFalse(TsgHubUi.running(event, Instant.parse("2026-10-05T07:59:59Z")));
		assertTrue(TsgHubUi.running(event, Instant.parse("2026-10-05T08:00:00Z")));
		assertFalse(TsgHubUi.running(event, Instant.parse("2026-10-12T08:00:00Z")));
	}

	@Test
	public void legacyDatesUseTheEventZone()
	{
		JsonObject event = new JsonObject();
		event.addProperty("type", "skill");
		event.addProperty("startDate", "2026-10-03");
		event.addProperty("endDate", "2026-10-04");
		assertEquals(Instant.parse("2026-10-02T14:00:00Z"), TsgHubUi.eventStart(event));
		assertEquals(Instant.parse("2026-10-04T13:00:00Z"), TsgHubUi.eventEnd(event));
		event.addProperty("timeZone", "Australia/Perth");
		assertEquals(Instant.parse("2026-10-02T16:00:00Z"), TsgHubUi.eventStart(event));
		assertEquals(Instant.parse("2026-10-04T16:00:00Z"), TsgHubUi.eventEnd(event));
	}

	@Test
	public void customEvents()
	{
		JsonObject config = new JsonObject();
		config.addProperty("startsAt", "2026-10-04T08:00:00Z");
		JsonObject event = new JsonObject();
		event.addProperty("type", "drop-party");
		event.addProperty("endDate", "2026-10-04");
		event.addProperty("status", "active");
		event.add("config", config);
		assertEquals(Instant.parse("2026-10-04T08:00:00Z"), TsgHubUi.eventStart(event));
		assertNull(TsgHubUi.eventEnd(event));
		assertTrue(TsgHubUi.running(event, NOW));
		event.addProperty("status", "ended");
		assertEquals("ended", TsgHubUi.eventRelative(event));
	}
}

package com.tsghub;

import static org.junit.Assert.assertEquals;

import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneOffset;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;

public class EventsPanelTest
{
	private Clock original;

	@Before
	public void fixClock()
	{
		original = TsgHubUi.clock;
		TsgHubUi.clock = Clock.fixed(Instant.parse("2026-10-04T02:00:00Z"), ZoneOffset.UTC);
	}

	@After
	public void restoreClock()
	{
		TsgHubUi.clock = original;
	}

	private static JsonObject event(String json)
	{
		return new JsonParser().parse(json).getAsJsonObject();
	}

	@Test
	public void eventCountdown()
	{
		assertEquals("7d 6h left", TsgHubUi.eventCountdown(event("{\"status\":\"active\",\"startsAt\":\"2026-09-20T09:00:00Z\",\"endsAt\":\"2026-10-11T08:00:00Z\"}")));
		assertEquals("in 6h", TsgHubUi.eventCountdown(event("{\"status\":\"scheduled\",\"startsAt\":\"2026-10-04T08:00:00Z\",\"endsAt\":\"2026-10-04T10:00:00Z\"}")));
		assertEquals("TBD", TsgHubUi.eventCountdown(event("{\"status\":\"scheduled\"}")));
	}

	@Test
	public void eventDetail()
